mapper.select:
SELECT m.*
FROM ts_agent_chat_message m
INNER JOIN ts_agent_chat_session s ON s.id = m.session_id
WHERE s.user_id = #{userId}
  AND s.is_deleted = 0
  AND s.session_status != 'deleted'
  AND m.is_deleted = 0

    AND m.session_id = #{sessionId}


    AND m.role_type = #{roleType}


    AND m.message_status = #{messageStatus}


    AND (
        m.content LIKE CONCAT('%', #{keyword}, '%')
        OR m.content_raw LIKE CONCAT('%', #{keyword}, '%')
    )

ORDER BY m.message_no ASC, m.id ASC

SELECT COUNT(1)
FROM ts_agent_chat_session
WHERE id = #{sessionId}
  AND user_id = #{userId}
  AND is_deleted = 0
  AND session_status != 'deleted'

SELECT m.*
FROM ts_agent_chat_message m
WHERE m.session_id = #{sessionId}
  AND m.is_deleted = 0
ORDER BY m.message_no DESC, m.id DESC
LIMIT #{limit}
